export const motifFor = (emoji: string) => (MOTIFS[FROM_EMOJI[emoji]] ? FROM_EMOJI[emoji] : 'star');
export const motifSvg = (key: string, p: Pal, size = 100) => `<svg viewBox="0 0 100 100" width="${size}" height="${size}" aria-hidden="true">${(MOTIFS[key] ?? MOTIFS.star)(p)}</svg>`;

/* ── patterns: small tiles for washi tape, borders and chapter pages ── */
export type PatternId = 'dots' | 'stripes' | 'gingham' | 'snow' | 'hearts' | 'stars' | 'leaves' | 'waves' | 'confetti' | 'checks' | 'blossoms' | 'diamonds';
export function patternDef(id: string, kind: PatternId, p: Pal, scale = 1): string {
  const s = (n: number) => +(n * scale).toFixed(2);
  const bg = light(p.s, 0.25), a = p.a, b = light(p.a, 0.45);
  const tile = (w: number, h: number, inner: string, rot = 0) => `<pattern id="${id}" width="${s(w)}" height="${s(h)}" patternUnits="userSpaceOnUse"${rot ? ` patternTransform="rotate(${rot})"` : ''}><g transform="scale(${scale})"><rect width="${w}" height="${h}" fill="${bg}"/>${inner}</g></pattern>`;
  switch (kind) {
    case 'dots': return tile(12, 12, `<circle cx="3" cy="3" r="1.8" fill="${a}"/><circle cx="9" cy="9" r="1.8" fill="${b}"/>`);
    case 'stripes': return tile(10, 10, `<rect width="5" height="10" fill="${b}"/>`, 45);
    case 'gingham': return tile(12, 12, `<rect width="6" height="12" fill="${a}" opacity=".35"/><rect width="12" height="6" fill="${a}" opacity=".35"/>`);
    case 'checks': return tile(12, 12, `<rect width="6" height="6" fill="${a}"/><rect x="6" y="6" width="6" height="6" fill="${a}"/>`);
    case 'snow': return tile(16, 16, `<g stroke="${WHITE}" stroke-width="1.2" stroke-linecap="round"><path d="M4 1 V7 M1 4 H7 M2 2 L6 6 M6 2 L2 6"/></g><circle cx="12" cy="12" r="1.3" fill="${WHITE}"/>`);
    case 'hearts': return tile(14, 14, `<path d="${heartPath(4, 4, 2.6)}" fill="${a}"/><path d="${heartPath(11, 11, 2)}" fill="${b}"/>`);
    case 'stars': return tile(16, 16, `<polygon points="${star5(4, 4, 3.4, 1.4)}" fill="${GOLD}"/><circle cx="12" cy="11" r="1" fill="${a}"/>`);
    case 'leaves': return tile(16, 16, `<ellipse cx="5" cy="5" rx="4" ry="1.8" fill="${LEAF2}" transform="rotate(-35 5 5)"/><ellipse cx="12" cy="12" rx="3.4" ry="1.6" fill="${ORANGE}" transform="rotate(30 12 12)"/>`);
    case 'waves': return tile(16, 8, `<path d="M0 5 Q4 1 8 5 T16 5" stroke="${a}" stroke-width="1.6" fill="none"/>`);
    case 'confetti': return tile(18, 18, `<rect x="2" y="3" width="4" height="2" fill="${RED}" transform="rotate(20 4 4)"/><rect x="11" y="9" width="4" height="2" fill="${SKY}" transform="rotate(-30 13 10)"/><circle cx="6" cy="14" r="1.2" fill="${GOLD}"/><circle cx="15" cy="3" r="1.1" fill="${a}"/>`);
    case 'blossoms': return tile(16, 16, `${petals(5, 5, 5, 2, 1.6, 1.9, PINK)}<circle cx="5" cy="5" r="0.9" fill="${GOLD}"/><circle cx="12" cy="12" r="1.2" fill="${b}"/>`);
    case 'diamonds': return tile(12, 12, `<path d="M6 1 L11 6 L6 11 L1 6 Z" fill="${b}"/>`);
  }
}

/* ── garlands: strung across the top of a cover, a section page or the last page ── */
export type GarlandId = 'lights' | 'bunting' | 'leaves' | 'lanterns' | 'fanous' | 'papel' | 'marigolds' | 'stars' | 'hearts' | 'snow' | 'blossoms' | 'pennants' | 'shells';
/** A garland across a width of 100 (draws in 0–100 × 0–26). */
export function garlandSvg(kind: GarlandId, p: Pal, seed = 0, colours?: string[]): string {
  const sag = (x: number) => 4 + Math.sin((x / 100) * Math.PI) * 12;
  const string = `<path d="M-2 4 Q50 ${4 + 24} 102 4" stroke="${dark(p.i, 0)}" stroke-width=".6" fill="none" opacity=".7"/>`;
  const at = (n: number) => Array.from({ length: n }, (_, k) => { const x = 4 + (k * 92) / (n - 1); return [x, sag(x)] as const; });
  const cols = colours?.length ? colours : [p.a, GOLD, light(p.a, 0.45), mix(p.s, p.a, 0.3)];
  switch (kind) {
    case 'lights': return string + at(13).map(([x, y], k) => `<rect x="${x - 0.9}" y="${y - 0.4}" width="1.8" height="1.8" fill="${dark(p.i, 0)}"/><ellipse cx="${x}" cy="${y + 3.4}" rx="1.9" ry="2.8" fill="${[RED, GOLD, '#3f9a52', SKY, PINK][(k + seed) % 5]}"/><ellipse cx="${x}" cy="${y + 3.4}" rx="4" ry="4.6" fill="${[RED, GOLD, '#3f9a52', SKY, PINK][(k + seed) % 5]}" opacity=".18"/>`).join('');
    case 'bunting': return string + at(11).map(([x, y], k) => `<path d="M${x - 3.6} ${y} L${x + 3.6} ${y} L${x} ${y + 8} Z" fill="${cols[(k + seed) % cols.length]}"/>`).join('');
    case 'pennants': return string + at(9).map(([x, y], k) => `<path d="M${x - 4} ${y} L${x + 4} ${y} L${x + 4} ${y + 7} L${x} ${y + 5} L${x - 4} ${y + 7} Z" fill="${colours?.length ? colours[k % colours.length] : k % 2 ? p.a : WHITE}" stroke="${dark(p.i, 0)}" stroke-width=".3"/>`).join('');
    case 'papel': return string + at(8).map(([x, y], k) => `<path d="M${x - 5} ${y} H${x + 5} V${y + 9} L${x + 3.5} ${y + 10.5} L${x + 2} ${y + 9} L${x} ${y + 10.5} L${x - 2} ${y + 9} L${x - 3.5} ${y + 10.5} L${x - 5} ${y + 9} Z" fill="${['#e0559a', '#f0a02a', '#3fa0d9', '#5cb85c', '#8a6bc6'][(k + seed) % 5]}"/><path d="${heartPath(x, y + 4.5, 1.6)}" fill="${WHITE}" opacity=".9"/><circle cx="${x - 2.6}" cy="${y + 2.4}" r=".7" fill="${WHITE}"/><circle cx="${x + 2.6}" cy="${y + 2.4}" r=".7" fill="${WHITE}"/>`).join('');
    case 'lanterns': return string + at(6).map(([x, y]) => `<g transform="translate(${x - 4} ${y}) scale(.08)">${MOTIFS.lantern(p)}</g>`).join('');
    case 'fanous': return string + at(7).map(([x, y], k) => `<path d="M${x} ${y} V${y + 1 + (k % 2) * 3}" stroke="${dark(p.i, 0)}" stroke-width=".3"/><g transform="translate(${x - 4} ${y + 1 + (k % 2) * 3}) scale(.08)">${MOTIFS[k % 3 === 1 ? 'crescent' : 'fanous'](p)}</g>`).join('');
    case 'marigolds': return string + at(16).map(([x, y], k) => `<circle cx="${x}" cy="${y + 1.5}" r="2.4" fill="${k % 2 ? '#f0a02a' : '#e07a1f'}"/><circle cx="${x}" cy="${y + 1.5}" r="1" fill="#c2561a"/>`).join('') + at(4).map(([x, y]) => `<ellipse cx="${x}" cy="${y + 4.6}" rx="1.6" ry="3" fill="${LEAF}"/>`).join('');
    case 'leaves': return string + at(14).map(([x, y], k) => `<ellipse cx="${x}" cy="${y + 2.6}" rx="2" ry="3.6" fill="${[ORANGE, '#c8423a', GOLD, '#a5672a', LEAF2][(k + seed) % 5]}" transform="rotate(${k % 2 ? 25 : -25} ${x} ${y + 2.6})"/>`).join('');
    case 'stars': return string + at(9).map(([x, y], k) => `<path d="M${x} ${y} V${y + 2 + (k % 3) * 2}" stroke="${dark(p.i, 0)}" stroke-width=".3"/><polygon points="${star5(x, y + 4 + (k % 3) * 2, 2.6, 1.1)}" fill="${k % 2 ? GOLD : light(GOLD, 0.4)}"/>`).join('');
    case 'hearts': return string + at(10).map(([x, y], k) => `<path d="${heartPath(x, y + 3, 2.4)}" fill="${(colours?.length ? colours : [p.a, PINK, light(p.a, 0.4)])[(k + seed) % (colours?.length || 3)]}"/>`).join('');
    case 'snow': return at(12).map(([x], k) => `<path d="M${x} 0 V${6 + (k % 4) * 3}" stroke="${light(p.i, 0.6)}" stroke-width=".3"/><g transform="translate(${x} ${7 + (k % 4) * 3}) scale(.06) translate(-50 -50)">${MOTIFS.snowflake(p)}</g>`).join('');
    case 'blossoms': return `<path d="M-2 3 Q30 12 60 6 T102 8" stroke="#6b4226" stroke-width="1.2" fill="none"/>` + at(10).map(([x], k) => `<g transform="translate(${x} ${6 + (k % 3) * 2}) scale(.07) translate(-50 -50)">${MOTIFS.blossom(p)}</g>`).join('');
    case 'shells': return string + at(7).map(([x, y], k) => `<g transform="translate(${x - 3} ${y}) scale(.065)">${MOTIFS[k % 2 ? 'starfish' : 'shell'](p)}</g>`).join('');
  }
}
